export function NavigationRail({
  position = "{{position}}",
  width = {{width}},
  accent = "{{accent}}",
  labels = {{labels}},
}) {
  const items = ["Home", "Search", "Settings"];
  return (
    <div style={{ display: "flex", flexDirection: position === "right" ? "row-reverse" : "row", height: 150, fontFamily: "system-ui, sans-serif", fontSize: 11, color: "#241430", border: "1px solid #24143022" }}>
      <nav style={{ flex: "none", boxSizing: "border-box", width, background: "#241430", display: "flex", flexDirection: "column", alignItems: "center", gap: 16, paddingTop: 16 }}>
        {items.map((label, i) => (
          <div key={label} style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 4, color: i === 0 ? accent : "#FAF7F2aa" }}>
            <span style={{ width: 20, height: 20, borderRadius: 6, background: i === 0 ? accent : "#FAF7F244" }} />
            {labels && <small>{label}</small>}
          </div>
        ))}
      </nav>
      <div style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", background: "#FAF7F2", color: "#24143066", fontSize: 13 }}>Content</div>
    </div>
  );
}
